// 提取文字中的网址，每个网址作为一个候选。
function main(text) {
  const starts = /https?:\/\//gi, adjacent = /[,;]https?:\/\//iy;
  const stop = /[\s<>"'，。；、！？「」『』【】《》“”‘’（）]/;
  const links = new Set();
  let match;
  while ((match = starts.exec(text))) {
    let start = match.index;
    const marker = text[start - 1];
    if ('*_~`'.includes(marker) && marker) {
      while (start > 0 && text[start - 1] === marker) start--;
    }
    const wrap = text.slice(start, match.index);
    let end = starts.lastIndex, depth = 0, brackets = 0;
    for (; end < text.length; end++) {
      const c = text[end];
      if (wrap && text.startsWith(wrap, end) &&
          (marker === '`' || !/[\p{L}\p{N}]/u.test(text[end + wrap.length] || ''))) break;
      if (stop.test(c) || (c === ')' && !depth) || (c === ']' && !brackets)) break;
      if (c === ',' || c === ';') {
        adjacent.lastIndex = end;
        if (adjacent.test(text)) break;
      }
      if (c === '[') brackets++;
      if (c === ']') brackets--;
      if (c === '(') depth++;
      if (c === ')') depth--;
    }
    const link = text.slice(match.index, end).replace(/[.,;:!?]+$/, '');
    if (/^https?:\/\/[^/?#\s]+/i.test(link)) links.add(link);
    starts.lastIndex = end;
  }
  return [...links];
}

// 按换行拆分文字，跳过空行，每行作为一个候选。
function main(text) {
  return text.split(/\r\n?|\n/).map(line => line.trim()).filter(Boolean);
}

// 提取标为验证码或取件码的数字，保留开头的零。
function main(text) {
  const label = '(?:验证码|校验码|取件码|提货码|\\b(?:verification code|pickup code|OTP)\\b)';
  const code = '([0-9]{1,4}(?:-[0-9]{1,5}){1,3}|[0-9]{4,8})(?![A-Za-z0-9_-])';
  const after = label + '\\s*(?:(?:为|是|is)\\s*)?[:：]?\\s*' + code;
  const before = '(?:^|[^A-Za-z0-9_-])' + code + '\\s*(?:[是为](?:您|你)?的?|is\\s+(?:(?:your|the)\\s+)?)\\s*' + label;
  return [...new Set(Array.from(text.matchAll(new RegExp(after + '|' + before, 'gi')), m => m[1] || m[2]))];
}

// 移除网址中已知的跟踪参数，保留其他参数和页面锚点。
function main(text) {
  const url = text.trim();
  if (!/^https?:\/\/[^\s/?#]+[^\s]*$/i.test(url)) return [];
  const parts = url.match(/^([^?#]*)(?:\?([^#]*))?(#.*)?$/);
  if (!parts[2]) return url;
  const params = parts[2].split('&');
  const keep = params.filter(p => !/^(?:utm_[^=]+|fbclid|gclid)(?:=|$)/i.test(p));
  if (keep.length === params.length) return url;
  const query = keep.filter(Boolean).join('&');
  return parts[1] + (query ? '?' + query : '') + (parts[3] || '');
}

// 合并同一段内的换行，保留空行分隔的段落。
function main(text) {
  return text.replace(/
?/g, '
').trim().split(/
(?:[ 	]*
)+/).map(paragraph =>
    paragraph.split('
').map(line => line.trim()).reduce((left, right) =>
      left + (/[\p{Script=Han}，。！？：；、]$/u.test(left) || /^[\p{Script=Han}，。！？：；、]/u.test(right) ? '' : ' ') + right)
  ).join('

');
}

// 删除完全相同的行，保留第一次出现的顺序。
function main(text) {
  return [...new Set(text.split(/\r\n?|\n/))].join('\n');
}

// 提取文字中的邮箱地址，每个邮箱作为一个候选。
function main(text) {
  return [...new Set(text.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi) || [])];
}

// 按逗号、顿号或分号拆分文字，每项作为一个候选。
function main(text) {
  return text.split(/[,，、;；]/).map(item => item.trim()).filter(Boolean);
}

// 在中文与相邻的英文、数字之间补上空格。
function main(text) {
  return text.replace(/(\p{Script=Han})([A-Za-z0-9])/gu, '$1 $2')
             .replace(/([A-Za-z0-9])(\p{Script=Han})/gu, '$1 $2');
}

// 将 GitHub 文件页面链接转换为原始文件的直链。
function main(text) {
  const file = text.trim().match(/^https:\/\/github\.com\/([^/?#\s]+\/[^/?#\s]+)\/blob\/([^/?#\s]+\/[^?#\s]+)(?:[?#][^\s]*)?$/i);
  return file ? 'https://raw.githubusercontent.com/' + file[1] + '/' + file[2] : [];
}
